import { Router } from 'express';
import { ProjectController } from './controllers/ProjectController';
import { TaskController } from './controllers/TaskController';
import { UserController } from './controllers/UserController';

export interface Controllers {
  users: UserController;
  projects: ProjectController;
  tasks: TaskController;
}

export function createRouter({ users, projects, tasks }: Controllers): Router {
  const router = Router();

  router.post('/users', users.create);
  router.get('/users', users.list);

  router.post('/projects', projects.create);
  router.get('/projects', projects.list);

  router.post('/projects/:projectId/tasks', tasks.create);
  router.get('/projects/:projectId/tasks', tasks.listByProject);

  router.put('/tasks/:taskId/assignee', tasks.assign);
  router.post('/tasks/:taskId/done', tasks.markDone);

  return router;
}

